SELECT * FROM ( SELECT COUNT(*) OVER() AS TOTAL_RECORD_COUNT, TB.* FROM ( SELECT ROW_NUMBER() OVER (ORDER BY A.PROGRM_FILE_NM ASC) AS RNUM, A.PROGRM_FILE_NM, A.PROGRM_STRE_PATH, A.PROGRM_KOREAN_NM, A.PROGRM_DC, A.URL, A.TEST_URL FROM COMTNPROGRMLIST A WHERE 1=1
AND ( A.PROGRM_FILE_NM LIKE CONCAT('%', #{params.searchKeyword}, '%') OR A.PROGRM_KOREAN_NM LIKE CONCAT('%', #{params.searchKeyword}, '%') )
) TB ) TA ORDER BY TA.RNUM DESC LIMIT #{params.recordCountPerPage} OFFSET #{params.firstIndex}

SELECT A.PROGRM_FILE_NM, A.PROGRM_STRE_PATH, A.PROGRM_KOREAN_NM, A.PROGRM_DC, A.URL
FROM COMTNPROGRMLIST A
WHERE A.PROGRM_FILE_NM = #{progrmFileNm}

